  it('materializes and renders one bounded 500-recipient page within the local database budget', async () => {
    await c.query('BEGIN');
    try {
      const { round, cycle } = await seedMaterializingRound('500-recipient render scale');
      await c.query(`INSERT INTO public.rebook_round_commands
        (command_id,academy_profile_id,actor_user_id,round_id,command_kind,request_fingerprint,
         canonical_payload,result_receipt,result_receipt_canonical,result_receipt_digest)
        VALUES (gen_random_uuid(),$1,$3,$2,'create',extensions.digest('{}','sha256'),'{}','{}',
                pg_catalog.convert_to('{}','UTF8'),
                pg_catalog.sha256(pg_catalog.convert_to('{}','UTF8')))`,
      [ACADEMY, round, FIXTURE_ACTOR]);
      const slot = (await c.query(`INSERT INTO public.availability_slots
        (id,trainer_id,academy_profile_id,source_cycle_id,start_time,end_time,max_participants,member_window_ends_at)
        VALUES (gen_random_uuid(),$1,$2,$3,now()+interval '1 day',now()+interval '1 day 1 hour',4,
                now()+interval '7 days') RETURNING id`, [await testTrainer(c), ACADEMY, cycle])).rows[0].id;

      await c.query(`CREATE TEMP TABLE abc27_scale_subjects ON COMMIT DROP AS
        SELECT n,gen_random_uuid() AS user_id,gen_random_uuid() AS profile_id,
               gen_random_uuid() AS claim_id,gen_random_uuid() AS recipient_id
          FROM generate_series(1,$1::int) AS n`, [MATERIALIZATION_SCALE_RECIPIENTS]);
      await c.query(`INSERT INTO auth.users(id) SELECT user_id FROM abc27_scale_subjects`);
      // The signup trigger already minted one profile per user; the fixture adopts those ids
      // rather than inserting a second profile per user (which `profiles_user_id_key` refuses).
      await c.query(`UPDATE abc27_scale_subjects s SET profile_id = p.id
                       FROM public.profiles p WHERE p.user_id = s.user_id`);
      await c.query(`UPDATE public.profiles p
                        SET preferred_language = CASE WHEN s.n % 2 = 0 THEN 'nl-NL' ELSE 'en-US' END
                       FROM abc27_scale_subjects s WHERE p.user_id = s.user_id`);
      await c.query(`INSERT INTO public.notification_contacts
        (user_id,channel,destination_normalized,destination_redacted,verified_at,consent_status,
         consent_scope,is_primary)
        SELECT user_id,'email',user_id::text || '@scale.example.test','s***@scale.example.test',
               clock_timestamp(),'unknown','global',true
          FROM abc27_scale_subjects`);
      await c.query(`INSERT INTO public.slot_priority_claims(id,slot_id,player_id,status)
        SELECT claim_id,$1,profile_id,'pending' FROM abc27_scale_subjects`, [slot]);
      await c.query(`INSERT INTO public.rebook_round_recipients
        (id,rebook_round_id,academy_profile_id,recipient_player_profile_id,captured_at)
        SELECT recipient_id,$1,$2,profile_id,clock_timestamp() FROM abc27_scale_subjects`, [round, ACADEMY]);
      await c.query(`INSERT INTO public.rebook_round_recipient_claim_sources
        (rebook_round_recipient_id,rebook_round_id,academy_profile_id,source_claim_id,
         source_slot_id,source_cycle_id,claimed_player_profile_id,claim_status,captured_at)
        SELECT recipient_id,$1,$2,claim_id,$3,$4,profile_id,'pending',clock_timestamp()
          FROM abc27_scale_subjects`, [round, ACADEMY, slot, cycle]);

      await c.query('SET ROLE service_role');
      let explain: Record<string, unknown>;
      try {
        const measured = await c.query(`EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)
          SELECT * FROM public.rebook_round_materialize(1,${MATERIALIZATION_SCALE_RECIPIENTS})`);
        [explain] = measured.rows[0]['QUERY PLAN'] as Record<string, unknown>[];
      } finally {
        await c.query('RESET ROLE');
      }

      const plan = explain.Plan as Record<string, unknown>;
      expect(plan['Node Type']).toBe('Function Scan');
      expect(plan['Actual Rows']).toBe(1);
      expect(explain['Execution Time']).toBeTypeOf('number');
      expect(explain['Execution Time'] as number).toBeLessThan(MATERIALIZATION_SCALE_BUDGET_MS);

      const evidence = (await c.query(`SELECT
        (SELECT count(*)::int FROM public.rebook_round_recipients WHERE rebook_round_id=$1) AS recipients,
        (SELECT count(*)::int FROM public.rebook_round_recipient_claim_sources WHERE rebook_round_id=$1) AS sources,
        (SELECT count(*)::int FROM public.notification_outbox
          WHERE related_rebook_round_id=$1 AND event_type='rebook_member_open_player'
            AND channel='email' AND status='pending') AS pending,
        (SELECT count(*)::int FROM public.notification_outbox
          WHERE related_rebook_round_id=$1 AND payload ? 'subject' AND payload ? 'html') AS rendered,
        (SELECT count(*)::int FROM public.notification_outbox
          WHERE related_rebook_round_id=$1 AND payload->>'locale'='nl') AS nl,
        (SELECT count(*)::int FROM public.notification_outbox
          WHERE related_rebook_round_id=$1 AND payload->>'locale'='en') AS en,
        (SELECT lifecycle FROM public.rebook_rounds WHERE id=$1) AS lifecycle`, [round])).rows;
      // ── DECISION-ONLY FINALIZATION, AT SCALE ────────────────────────────────────────────────
      //
      // All 500 recipients are deliverable, so the page produced 500 QUEUED transport rows and
      // ZERO decisions — and the round therefore stays `materializing`.
      //
      // The previous expectation here was `materialized`, and that is exactly the defect this
      // unit exists to remove: a round reporting completion while 500 messages had merely been
      // enqueued, none of them dispatched, and any failure from that point on silently lost.
      // Finalization now consumes immutable decisions only, so an in-flight population cannot
      // finalize a round no matter how large it is.
      expect(evidence).toEqual([{
        recipients: MATERIALIZATION_SCALE_RECIPIENTS,
        sources: MATERIALIZATION_SCALE_RECIPIENTS,
        pending: MATERIALIZATION_SCALE_RECIPIENTS,
        rendered: MATERIALIZATION_SCALE_RECIPIENTS,
        nl: MATERIALIZATION_SCALE_RECIPIENTS / 2,
        en: MATERIALIZATION_SCALE_RECIPIENTS / 2,
        lifecycle: 'materializing',
      }]);
      // The discriminator for the claim above: not one of the 500 has a decision yet, so nothing
      // about this round is complete.
      expect((await c.query(`SELECT count(*)::int AS n
        FROM public.rebook_round_recipient_decisions WHERE rebook_round_id=$1`, [round])).rows[0].n).toBe(0);
    } finally {
      await c.query('RESET ROLE').catch(() => undefined);
      await c.query('ROLLBACK');
    }
  }, 30_000);

