      'rebook_round_apply_command_as_actor(uuid, uuid, text, text, uuid, integer, text, date, date, integer, integer, integer, text, boolean, text, boolean, boolean, numeric, boolean, integer, text, text, text, text, text, text, date[], date[], text[], uuid[], uuid[], uuid[], bytea)',
      'rebook_round_apply_lifecycle_command_as_actor(uuid, uuid, text, uuid, integer, text, text)',
