      'rebook_round_apply_normalized_core(uuid, uuid, text, text, uuid, uuid, integer, text, date, date, integer, integer, integer, text, boolean, text, boolean, boolean, numeric, boolean, integer, text, text, text, text, text, text, date[], date[], text[], uuid[], uuid[], uuid[], bytea)',
      // ── STAGE 7.4-B: the canonical v2 grammar. Relation-free renderers plus the one pre-image
      //    and fingerprint; they sit between the apply cores and the predecessor canonicalizer.
      'rebook_round_canon_absent()',
      'rebook_round_canon_bool(boolean)',
      'rebook_round_canon_date(date)',
      'rebook_round_canon_int(bigint)',
      'rebook_round_canon_num(numeric)',
