      'rebook_round_canon_text(text)',
      'rebook_round_canon_time(time without time zone)',
      'rebook_round_canon_ts(timestamp with time zone)',
      'rebook_round_canon_uuid(uuid)',
      'rebook_round_command_canonical(uuid, text, uuid, text, timestamp with time zone, timestamp with time zone, uuid[], text[], text[], uuid[])',
      'rebook_round_command_fingerprint(jsonb)',
      'rebook_round_command_lookup_by_review_as_actor(uuid, text, bytea)',
      'rebook_round_command_lookup_by_review_core(uuid, uuid, text, bytea)',
      'rebook_round_command_status_as_actor(uuid, uuid)',
      'rebook_round_command_status_core(uuid, uuid, uuid)',
      'rebook_round_eligible_recipients(uuid, uuid[])',
      'rebook_round_freeze_and_snapshot(uuid)',
      'rebook_round_generate_occurrences(text, date, integer, time without time zone, integer, integer, date, date[], date[])',
      'rebook_round_intent_canonical_v2(text[])',
      'rebook_round_intent_fingerprint_v2(text)',
      'rebook_round_legacy_review_summary(integer)',
      'rebook_round_lifecycle_transitions()',
      'rebook_round_materialize(integer, integer)',
      'rebook_round_max_children()',
      'rebook_round_max_claim_sources()',
      // ── STAGE 7.4-B ceilings. Listed for the same reason as their predecessors: this inventory
