      namesTheRelation: true,
      readersExcluded: true,
      invisibleAtAcquisition: true,
      threeOutcomes: true,
      manualAbortAndRetry: true,
      hasAPreflightQuery: true,
      censusCoversTheWholeLockSet: [],
      censusNamesTheRelation: true,
      censusReportsTheTransactionId: true,
      censusToleratesAnAbsentRelation: true,
      forbidsWeakeningTheLock: true,
      migrationCitesTheGuide: true,
      censusSeesPreparedHolders: true,
      censusStillUsesIsDistinctFrom: false,
      censusQualifiesFunctionsTypesAndOperators: true,
      qualificationPinCatchesTheRetiredForms: 7,
      qualificationPinAcceptsTheShippedForms: 0,
      namesTheUnqualifiableConstructs: true,
      splitsTheTwoInterceptionsCorrectly: true,
      groupsTypesWithFunctions: false,
      censusProseNamesTheExplicitPgTempOrdering: true,
      censusProseCreditsTheImpostorSchema: true,
      censusProseSeparatesFabricationFromLoudFailure: true,
      censusIsShadowProof: true,
      // Eight: five in the prose that explains what the psql variable is, what it cannot protect
      // against, that there is no such substitution elsewhere, and what an UNSET variable renders
      // as; the identity lookup; and each of the two resolutions.
      quotedGidSubstitutions: 8,
      commandsThatSubstituteAGid: [],
      unquotedGidSubstitutions: 0,
      censusExplainsWhy: true,
      censusUsesTheTwoHop: true,
      censusExplainsTheTwoHop: true,
      migrationUsesTheSamePath: true,
